args.CodeContent:
$logPath = "C:\Users\Joy\.gemini\antigravity\brain\56fd65fe-5ae8-4173-a836-7a5c996aabf6\.system_generated\logs\transcript_full.jsonl"
$outputFile = "scratch\last_appjs_content.txt"

# Read transcript line by line and find content
$lines = Get-Content -Path $logPath
Write-Host "Total lines in log: $($lines.Count)"

$matchCount = 0
for ($i = $lines.Count - 1; $i -ge 0; $i--) {
    $line = $lines[$i]
    if ($line -like "*app.js*") {
        Write-Host "Found match at line $i"
        $line | Out-File -FilePath "scratch\match_$i.json" -Encoding utf8
        $matchCount++
        if ($matchCount -gt 5) { break }
    }
}
